provider "aws" {
  region = "us-east-1"
}

variable "primary_zone_name" {
  default = "primary"
}

variable "cloudwatch_log_group_name" {
  default = "aws_route53_example_com"
}

variable "cloudwatch_log_resource_policy_name" {
  default = "route53-query-logging-policy"
}

resource "aws_route53_zone" "primary" {
  name = var.primary_zone_name
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name = var.cloudwatch_log_group_name
}

resource "aws_cloudwatch_log_resource_policy" "route53-query-logging-policy" {
  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = "logs:PutLogEvents"
        Resource = "${aws_cloudwatch_log_group.aws_route53_example_com.arn}"
      }
    ]
  })
  policy_name = var.cloudwatch_log_resource_policy_name
}

resource "aws_route53_query_log" "primary" {
  cloudwatch_log_group_arn = aws_cloudwatch_log_group.aws_route53_example_com.arn
  zone_id = aws_route53_zone.primary.zone_id
}

resource "aws_cloudwatch_log_stream" "primary" {
  log_group_name = aws_cloudwatch_log_group.aws_route53_example_com.name
  name = var.primary_zone_name
}
