  region = "us-east-1"
}

variable "db_instance_class" {
  default = "db.t3.micro"
}

resource "aws_vpc" "vpc_main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet_private" {
  vpc_id           = aws_vpc.vpc_main.id
  cidr_block       = "10.0.0.0/24"
  availability_zone = "us-east-1a"
  map_public_ip_on_launch = false
}

resource "aws_subnet" "subnet_public" {
  vpc_id           = aws_vpc.vpc_main.id
  cidr_block       = "10.0.1.0/24"
  availability_zone = "us-east-1b"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "sg_internal" {
  name   = "internal-sg"
  vpc_id = aws_vpc.vpc_main.id

  ingress {
    from_port   = 53
    to_port     = 53
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/24"]
  }
}

resource "aws_security_group" "sg_public" {
  name   = "public-sg"
  vpc_id = aws_vpc.vpc_main.id

  ingress {
    from_port   = 53
    to_port     = 53
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "db_subnet_group_main" {
  name        = "main-subnet-group"
  subnet_ids = [aws_subnet.subnet_private.id, aws_subnet.subnet_public.id]
}

resource "aws_db_instance" "db_internal" {
  instance_class = var.db_instance_class
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group_main.name
  vpc_security_group_ids = [aws_security_group.sg_internal.id]
  engine = "mysql"
  allocated_storage = 20
}

resource "aws_db_instance" "db_public" {
  instance_class = var.db_instance_class
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group_main.name
  vpc_security_group_ids = [aws_security_group.sg_public.id]
  engine = "mysql"
  allocated_storage = 20
}

resource "aws_route53_zone" "zone_private" {
  name = "private.example.com"
}

resource "aws_route53_zone" "zone_public" {
