```hcl
provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the web application"
  default     = "example.com"
}

resource "aws_s3_bucket" "web_app_bucket" {
  bucket = "my-web-app-bucket-${random_string.random_suffix.result}"
  acl    = "public-read"

  tags = {
    Name = "Web App Bucket"
  }
}

resource "aws_s3_bucket_policy" "web_app_bucket_policy" {
  bucket = aws_s3_bucket.web_app_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = ["s3:GetObject"]
        Resource = "${aws_s3_bucket.web_app_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_cloudfront_distribution" "web_app_distribution" {
  enabled = true

  origin {
    domain_name = aws_s3_bucket.web_app_bucket.bucket_domain_name
    origin_id   = "S3Origin"
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "allow-all"

    response_headers_policy_id = aws_cloudfront_response_headers_policy.web_app_response_headers_policy.id
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    ssl_support_method = "sni-only"
    acm_certificate_arn = "arn:aws:acm:us-east-1:123456789012:certificate/12345678-1234-1234-1234-123456789012"
  }

  logging_config {
    bucket = "my-web-app-logs.s3.amazonaws.com"
    include_cookies = false
    prefix = "logs/"
  }

  tags = {
    Name = "Web App Distribution"
  }
}

resource "aws_cloudfront_response_headers_policy" "web_app_response_headers_policy" {
  name = "Web App Response Headers Policy"

  cors_config {
    access_control_allow_credentials = false
    access_control_allow_headers = ["*"]
    access_control_allow_methods = ["GET", "HEAD", "OPTIONS"]
    access_control_allow_origins = ["*"]
    access_control_expose_headers = ["Content-Type", "Date"]
    access_control_max_age_seconds = 86400
  }

  security_headers_config {
    content_security_policy = "default-src 'self'; script-src 'self' https://cdn.example.com; style-src 'self' https://cdn.example.com"
    frame_options           = "DENY"
    referrer_policy         = "same-origin"
    x_frame_options         = "DENY"
    x_content_type_options = "nosniff"
  }

  strict_transport_security_config {
    enable              = true
    max_age_seconds     = 31536000
    include_subdomains = true
    preload             = true
  }
}

resource "aws_route53_zone" "web_app_zone" {
  name = var.domain_name
}

resource "aws_route53_record" "web_app_domain_record" {
  zone_id = aws_route53_zone.web_app_zone.zone_id
  name    = "www"
  type    = "CNAME"
  ttl     = 300

  alias {
    evaluate_target_health = true
    name                  = aws_cloudfront_distribution.web_app_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.web_app_distribution.hosted_zone_id
  }
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
}
```

