    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lambda_function" "pizza_order_handler" {
  function_name = "pizza_order_handler"
  role          = aws_iam_role.pizza_order_handler_role.arn
  handler       = "pizza_order_handler.handler"
  runtime       = "python3.8"
  timeout       = 30

  code {
    zip_file = base64encode(file("pizza_order_handler.zip"))
  }

  environment {
    variables = {
      LOG_LEVEL = "INFO"
    }
  }

  tags = {
    Name = "Pizza Order Handler"
  }
}

resource "aws_lex_bot" "pizza_order_bot" {
  name             = "pizza_order_bot"
  child_directed   = false
  description     = "Bot to handle pizza orders"
  detect_sentiment = true
  enable_model_improvements = true
  locale           = "en-US"
  nlu_intent_confidence_threshold = 0.8
  process_behavior = "DONT_INDEX"
  voice_id         = "Joanna"

  abort_statement {
    response_card = jsonencode({
      contentType = "application/vnd.amazonaws.template.v1.json"
      content = <<EOF
{
  "version": "1.0",
  "sessionAttributes": {},
  "dialogAction": {
    "type": "Close",
    "fulfillmentState": "Failed",
    "message": {
      "contentType": "PlainText",
      "content": "Sorry, we couldn't process your request."
    }
  }
}
EOF
    })
  }

  intent {
    intent_name = "OrderPizza"
    intent_version = "1"
  }

  message {
    content = "Hello! How can I assist you today?"
    content_type = "PlainText"
    group_number = 1
  }

  clarification_prompt {
    max_attempts = 2
    response_card = jsonencode({
      contentType = "application/vnd.amazonaws.template.v1.json"
      content = <<EOF
{
  "version": "1.0",
  "sessionAttributes": {},
  "dialogAction": {
    "type": "Prompt",
    "prompt": {
      "contentType": "PlainText",
      "content": "I'm sorry, I didn't understand that. Can you please repeat your request?"
    },
    "retries": 1
  }
}
EOF
    })
  }
}
