provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "firehose_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

resource "aws_subnet" "firehose_subnet" {
  vpc_id = aws_vpc.firehose_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "firehose_sg" {
  name = "firehose_sg"
  description = "Security group for Kinesis Firehose"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elasticsearch_domain" "firehose_es" {
  domain_name = "firehose-es"
  elasticsearch_version = "7.10"
  cluster_config {
    instance_count = 1
    instance_type = "t2.micro.elasticsearch"
  }
  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = [
          "es:*"
        ]
        Condition = {
          IpAddress = {
            "aws:SourceIp" = "0.0.0.0/0"
          }
        }
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name = "firehose-delivery-stream"
  destination {
    elasticsearch {
      index_name = "firehose-index"
      role_arn = aws_iam_role.firehose_role.arn
      cluster_endpoint = aws_elasticsearch_domain.firehose_es.endpoint
    }
  }

  tags = {
    Name = "firehose-delivery-stream"
  }
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Effect = "Allow"
        Action = [
          "es:DescribeElasticsearchDomain",
          "es:GetPipelineExecutionHistory",
          "es:ListTagsForResource"
        ]
        Resource = "arn:aws:es:*:*:*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetBucketLocation"
        ]
        Resource = "arn:aws:s3:::*"
      }
    ]
  })
}
