```hcl
provider "aws" {
  region = "us-west-2"
}

variable "log_group_name" {
  default = "kinesis-analytics-log-group"
}

variable "log_stream_name" {
  default = "kinesis-analytics-log-stream"
}

variable "application_name" {
  default = "kinesis-analytics-app"
}

resource "aws_cloudwatch_log_group" "kinesis-analytics-log-group" {
  name = var.log_group_name
  retention_in_days = 30
}

resource "aws_cloudwatch_log_stream" "kinesis-analytics-log-stream" {
  log_group_name = aws_cloudwatch_log_group.kinesis-analytics-log-group.name
  name = var.log_stream_name
}

resource "aws_kinesis_analytics_application" "kinesis-analytics-application" {
  name = var.application_name

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis-analytics-log-stream.arn
    role_arn       = aws_iam_role.kinesis-analytics-role.arn
  }

  inputs {
    name_prefix = "input-prefix"
    schema {
      record_format {
        record_format_type = "JSON"
        json_content_type = "JSON"
      }
      record_column {
        name = "column1"
        mapping = "$.column1"
        sql_type_name = "VARCHAR(255)"
      }
    }
  }

  outputs {
    name = "output-name"
    schema {
      record_format {
        record_format_type = "JSON"
        json_content_type = "JSON"
      }
      record_column {
        name = "column1"
        mapping = "$.column1"
        sql_type_name = "VARCHAR(255)"
      }
    }
  }

  reference_data_sources {
    s3 {
      bucket = "your-bucket-name"
      key = "your-key-name"
      reference_schema {
        record_format {
          record_format_type = "JSON"
          json_content_type = "JSON"
        }
        record_column {
          name = "column1"
          mapping = "$.column1"
          sql_type_name = "VARCHAR(255)"
        }
      }
    }
  }
}

resource "aws_iam_role" "kinesis-analytics-role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AmazonKinesisAnalyticsServiceRole"
  ]
}
```

### Explanation:
- **Inputs Block**: Added a `schema` block with a `record_format` and `record_column` to define the format of the input data.
- **Outputs Block**: Added a `schema` block with a `record_format` and `record_column` to define the format of the output data.
- **Reference Data Sources Block**: Added an `s3` block with a `bucket`, `key`, and `reference_schema` to specify the S3 bucket and key containing the reference data, along with its schema.

