  request_interval       = 30
  failure_threshold     = 3
  healthy_threshold     = 2
  unhealthy_threshold   = 2
  measure_latency       = true
  port                  = 80
  resource_path         = "/"
  tags = {
    Name = "primary_health_check"
  }
}

resource "aws_route53_health_check" "secondary_health_check" {
  type                  = "HTTP"
  fqdn                  = var.secondary_fqdn
  request_interval       = 30
  failure_threshold     = 3
  healthy_threshold     = 2
  unhealthy_threshold   = 2
  measure_latency       = true
  port                  = 80
  resource_path         = "/"
  tags = {
    Name = "secondary_health_check"
  }
}
