  tags = {
    Name = var.cluster_name
  }
}

resource "aws_subnet" "subnet1" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.1.0/24"

  tags = {
    Name = "${var.cluster_name}-subnet1"
  }
}

resource "aws_subnet" "subnet2" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.2.0/24"

  tags = {
    Name = "${var.cluster_name}-subnet2"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_role_subnet_attachment" {
  name       = "${var.cluster_name}-eks-cluster-role-subnet-attachment"
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"

  roles = [aws_iam_role.eks_cluster_role.name]

  depends_on = [aws_subnet.subnet1, aws_subnet.subnet2]
}

resource "aws_eks_cluster" "eks_cluster" {
