  }

  depends_on = [
    aws_iam_policy_attachment.eks_cluster_policy_attachment,
    aws_iam_policy_attachment.eks_service_policy_attachment,
    aws_iam_role_policy_attachment.eks_cluster_role_subnet_attachment
  ]
}

resource "local-exec" "configure_kubectl" {
