provider "aws" {
  region = "us-east-2"
  version = "~> 5.75"
}

variable "client_subnets" {
  default = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
}

variable "instance_type" {
  default = "t3.micro"
}

variable "security_groups" {
  default = ["sg-12345678"]
}

variable "kafka_version" {
  default = "2.8.1"
}

variable "number_of_broker_nodes" {
  default = 3
}

resource "aws_msk_cluster" "my_msk_cluster" {
  cluster_name = "my-msk-cluster"
  kafka_version = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    client_subnets = var.client_subnets
    instance_type = var.instance_type
    security_groups = var.security_groups

    az_distribution = "DEFAULT"
  }

  client_authentication {
    unauthenticated = true
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_key.arn
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/my-msk-cluster/logs"
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled = true
      }
    }
  }

  tags = {
    Name = "my-msk-cluster"
  }
}

resource "aws_kms_key" "msk_key" {
  description = "KMS key for MSK encryption"
}
```

