provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "kafka_version" {
  description = "Version of Kafka for the MSK cluster"
  default     = "2.8.2"
}

variable "number_of_broker_nodes" {
  description = "Number of broker nodes in the MSK cluster"
  default     = 3
}

variable "firehose_delivery_stream_name" {
  description = "Name of the Kinesis Firehose delivery stream"
  default     = "my-msk-firehose"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    instance_type = "t3.micro"
    security_groups = ["sg-12345678"]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/my-msk-cluster"
      }
    }
  }
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name = var.firehose_delivery_stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    bucket_arn = aws_s3_bucket.my-bucket.arn
    role_arn   = aws_iam_role.msk_firehose_role.arn

    buffering_interval = 60
    buffering_size    = 5000
    compression_format = "GZIP"
    prefix           = "msk-logs/"
    s3_backup_mode    = "Enabled"
  }
}

resource "aws_s3_bucket" "my-bucket" {
  bucket = "my-msk-firehose-bucket"
  acl    = "private"
}

resource "aws_iam_role" "msk_firehose_role" {
  name = "msk-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_firehose_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseDeliveryServiceRolePolicy"
  role       = aws_iam_role.msk_firehose_role.name
}
```

