provider "aws" {
  region = "us-west-2"  # Replace with your desired AWS region
}

variable "msk_cluster_name" {
  default = "my-msk-cluster"
}

variable "kafka_version" {
  default = "2.8.1"
}

variable "number_of_broker_nodes" {
  default = 3
}

variable "encryption_key_arn" {
  default = "arn:aws:kms:us-west-2:123456789012:key/your-kms-key-id"  # Replace with your KMS key ARN
}

resource "aws_msk_cluster" "my_msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]  # Replace with your subnet IDs
    instance_type = "t3.micro"
    security_groups = ["sg-12345678"]  # Replace with your security group ID
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = var.encryption_key_arn
  }
}

resource "aws_s3_bucket" "my_msk_cluster_encryption_bucket" {
  bucket = "my-msk-cluster-encryption-bucket-${var.msk_cluster_name}"  # Replace with your desired bucket name
  acl = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "aws:kms"
        kms_master_key_id = var.encryption_key_arn
      }
    }
  }
}
