provider "aws" {
  region = "us-west-2"
}

variable "msk_cluster_name" {
  default = "my-msk-cluster"
}

variable "kafka_version" {
  default = "2.8.1"
}

variable "number_of_broker_nodes" {
  default = 3
}

variable "jmx_exporter_lambda_code_bucket" {
  default = "my-lambda-code-bucket"
}

variable "jmx_exporter_lambda_code_key" {
  default = "jmx-exporter.zip"
}

variable "node_exporter_lambda_code_bucket" {
  default = "my-lambda-code-bucket"
}

variable "node_exporter_lambda_code_key" {
  default = "node-exporter.zip"
}

resource "aws_iam_role" "msk_cluster_jmx_exporter_role" {
  name = "${var.msk_cluster_name}-jmx-exporter-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_cluster_jmx_exporter_policy" {
  name = "${var.msk_cluster_name}-jmx-exporter-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "lambda:InvokeFunction",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = aws_lambda_function.jmx_exporter_lambda.arn
      }
    ]
  })
}

resource "aws_iam_role_attachment" "msk_cluster_jmx_exporter_role_attachment" {
  role = aws_iam_role.msk_cluster_jmx_exporter_role.name
  policy_arn = aws_iam_policy.msk_cluster_jmx_exporter_policy.arn
}

resource "aws_lambda_function" "jmx_exporter_lambda" {
  function_name = "${var.msk_cluster_name}-jmx-exporter"
  role = aws_iam_role.msk_cluster_jmx_exporter_role.arn
  handler = "com.example.JmxExporter::handleRequest"
  runtime = "java11"
  timeout = 30
  memory_size = 128
  code = {
    s3_bucket = var.jmx_exporter_lambda_code_bucket
    s3_key = var.jmx_exporter_lambda_code_key
  }
}

resource "aws_lambda_permission" "jmx_exporter_lambda_permission" {
  statement_id = "AllowInvokeJmxExporter"
  action = "lambda:InvokeFunction"
  function_name = aws_lambda_function.jmx_exporter_lambda.function_name
  principal = "kafka.amazonaws.com"
}

resource "aws_iam_role" "msk_cluster_node_exporter_role" {
  name = "${var.msk_cluster_name}-node-exporter-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_cluster_node_exporter_policy" {
  name = "${var.msk_cluster_name}-node-exporter-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "lambda:InvokeFunction",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = aws_lambda_function.node_exporter_lambda.arn
      }
    ]
  })
}

resource "aws_iam_role_attachment" "msk_cluster_node_exporter_role_attachment" {
  role = aws_iam_role.msk_cluster_node_exporter_role.name
  policy_arn = aws_iam_policy.msk_cluster_node_exporter_policy.arn
}

resource "aws_lambda_function" "node_exporter_lambda" {
  function_name = "${var.msk_cluster_name}-node-exporter"
  role = aws_iam_role.msk_cluster_node_exporter_role.arn
  handler = "com.example.NodeExporter::handleRequest"
  runtime = "java11"
  timeout = 30
  memory_size = 128
  code = {
    s3_bucket = var.node_exporter_lambda_code_bucket
    s3_key = var.node_exporter_lambda_code_key
  }
}

resource "aws_lambda_permission" "node_exporter_lambda_permission" {
  statement_id = "AllowInvokeNodeExporter"
  action = "lambda:InvokeFunction"
  function_name = aws_lambda_function.node_exporter_lambda.function_name
  principal = "kafka.amazonaws.com"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes
  enhanced_monitoring = "DEFAULT"

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    instance_type = "t3.micro"
    security_groups = ["sg-12345678"]
  }

  client_authentication {
    unauthenticated = true
  }

  configuration_info {
    arn = "arn:aws:kafka:us-west-2:123456789012:configuration/my-config/12345678901234567890123456789012"
    revision = 1
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/${var.msk_cluster_name}"
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled = true
        jmx_exporter_lambda_arn = aws_lambda_function.jmx_exporter_lambda.arn
      }
      node_exporter {
        enabled = true
        node_exporter_lambda_arn = aws_lambda_function.node_exporter_lambda.arn
      }
    }
  }
}
```

