provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "msk_cluster_role_name" {
  description = "Name of the IAM role for the MSK cluster"
  default     = "msk-cluster-role"
}

variable "msk_cluster_lambda_name" {
  description = "Name of the Lambda function for managing the MSK cluster"
  default     = "msk-cluster-lambda"
}

variable "msk_cluster_lambda_role" {
  description = "Name of the IAM role for the Lambda function"
  default     = "msk-cluster-lambda-role"
}

variable "msk_cluster_lambda_handler" {
  description = "Handler for the Lambda function"
  default     = "index.handler"
}

variable "msk_cluster_lambda_runtime" {
  description = "Runtime for the Lambda function"
  default     = "python3.8"
}

variable "msk_cluster_lambda_memory_size" {
  description = "Memory size for the Lambda function"
  default     = 128
}

variable "msk_cluster_lambda_timeout" {
  description = "Timeout for the Lambda function"
  default     = 30
}

variable "msk_cluster_lambda_description" {
  description = "Description for the Lambda function"
  default     = "Manages the MSK cluster"
}

variable "msk_cluster_lambda_code" {
  description = "Code for the Lambda function"
  default     = <<-EOF
def handler(event, context):
    # Add your logic here
    return {
        'statusCode': 200,
        'body': 'Hello, World!'
    }
EOF
}

resource "aws_iam_role" "msk_cluster_role" {
  name = var.msk_cluster_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_cluster_role_policy_attachment" {
  role       = aws_iam_role.msk_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "msk_cluster_lambda" {
  function_name = var.msk_cluster_lambda_name
  role                 = aws_iam_role.msk_cluster_role.arn
  handler              = var.msk_cluster_lambda_handler
  runtime              = var.msk_cluster_lambda_runtime
  memory_size           = var.msk_cluster_lambda_memory_size
  timeout               = var.msk_cluster_lambda_timeout
  description          = var.msk_cluster_lambda_description
  code                 = base64encode(var.msk_cluster_lambda_code)
  environment_variables = {
    CLUSTER_NAME = var.msk_cluster_name
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    instance_type = "t3.micro"
    security_groups = ["sg-12345678"]
  }

  client_authentication {
    unauthenticated = {}
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/${var.msk_cluster_name}"
      }
    }
  }
}
