provider "aws" {
  region = "us-east-2"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "kafka_version" {
  description = "Version of Kafka for the MSK cluster"
  default     = "2.8.1"
}

variable "number_of_broker_nodes" {
  description = "Number of broker nodes in the MSK cluster"
  default     = 3
}

variable "iam_role_name" {
  description = "Name of the IAM role for the MSK cluster"
  default     = "msk-cluster-role"
}

resource "aws_iam_role" "msk_cluster_role" {
  name = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lambda_function" "msk_cluster_lambda" {
  function_name = var.msk_cluster_name
  role           = aws_iam_role.msk_cluster_role.arn
  handler         = "index.handler"
  runtime         = "python3.8"
  timeout         = 30
  memory_size     = 128

  environment {
    variables = {
      KAFKA_BROKER_ARN = aws_msk_cluster.msk_cluster.bootstrap_brokers[0]
    }
  }

  dead_letter_config {
    target_arn = aws_sqs_queue.msk_cluster_dlq.arn
  }

  vpc_config {
    security_group_ids = [aws_security_group.msk_cluster_sg.id]
    subnet_ids         = [aws_subnet.msk_cluster_subnet.id]
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    instance_type = "t3.micro"
    client_subnets = [aws_subnet.msk_cluster_subnet.id]
    security_groups = [aws_security_group.msk_cluster_sg.id]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/${var.msk_cluster_name}"
      }
    }
  }

  vpc_connectivity {
    enabled = true
  }
}

resource "aws_sqs_queue" "msk_cluster_dlq" {
  queue_name = "${var.msk_cluster_name}-dlq"
}

resource "aws_security_group" "msk_cluster_sg" {
  name        = "${var.msk_cluster_name}-sg"
  description = "Security group for the MSK cluster"

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "msk_cluster_subnet" {
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-2a"
  vpc_id = aws_vpc.msk_cluster_vpc.id
}

resource "aws_vpc" "msk_cluster_vpc" {
  cidr_block = "10.0.0.0/16"
}
