}

resource "aws_s3_bucket" "msk_data" {
  bucket = "${var.msk_cluster_name}-data"
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose" {
  name = "${var.msk_cluster_name}-firehose"
  destination {
    s3 {
      bucket_arn = aws_s3_bucket.msk_data.arn
      role_arn   = aws_iam_role.msk_firehose_role.arn
    }
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = var.msk_kafka_version
  number_of_broker_nodes = var.msk_number_of_broker_nodes

  enhanced_monitoring = "DEFAULT"

  encryption_info {
    encryption_at_rest_kms_key_arn = var.msk_encryption_at_rest_kms_key_arn
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group_name = aws_cloudwatch_log_group.msk_logs.name
      }
    }
  }

  open_monitoring {
    prometheus_jmx_exporter {
      enabled = true
    }
  }

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    instance_type = "t3.micro"
    security_groups = ["sg-12345678"]
  }
}

