}

variable "account_id" {
  description = "AWS Account ID"
  default     = "your_account_id_here"
}

variable "region" {
  description = "AWS Region"
  default     = "us-west-2"
}

resource "aws_kms_key" "chime_logs" {
  description = "KMS Key for S3 Bucket Encryption"
}

resource "aws_s3_bucket" "log_bucket" {
  bucket = "chime-voice-connector-logs-${var.account_id}-${var.region}"
  acl    = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.chime_logs.key_id
        sse_algorithm     = "aws:kms"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket_encryption" {
  bucket = aws_s3_bucket.log_bucket.id
}

resource "aws_chime_voice_connector" "voice_connector" {
  name           = "chime-voice-connector-${var.account_id}-${var.region}"
  require_encryption = true

  logging {
    destination_arn = aws_s3_bucket.log_bucket.arn
  }
}
