```hcl
provider "aws" {
  region = "us-east-1"
}

variable "github_repo" {
  description = "The GitHub repository URL for the student code"
  default     = "https://github.com/example/cs-class-autograder.git"
}

variable "github_token" {
  description = "The GitHub personal access token for authentication"
  sensitive   = true
  default     = "your-github-personal-access-token-here"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket to store grading results"
  default     = "cs-class-autograder-results"
}

resource "aws_codebuild_project" "autograder_project" {
  name                  = "cs-class-autograder"
  service_role           = aws_iam_role.codebuild_service_role.arn
  badge_enabled         = false
  build_timeout         = 60
  concurrent_build_limit = 1
  description           = "Autograder for CS class"
  encryption_key         = aws_kms_key.codebuild_encryption_key.arn
  source_version        = "HEAD"
  tags = {
    Name = "cs-class-autograder"
  }

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:4.0"
    type        = "LINUX_CONTAINER"
  }

  source {
    type = "GITHUB"
    location = var.github_repo
    git_clone_depth = 1
    insecure_ssl = true
    report_build_status = true
    auth {
      type = "PERSONAL_ACCESS_TOKEN"
      token = var.github_token
    }
  }

  secondary_sources {
    source_identifier = "secondary-source"
    type             = "GITHUB"
    location         = var.github_repo
    git_clone_depth = 1
    insecure_ssl = true
    report_build_status = true
    auth {
      type = "PERSONAL_ACCESS_TOKEN"
      token = var.github_token
    }
  }

  secondary_source_versions {
    source_identifier = "secondary-source"
    source_version = "HEAD"
  }

  secondary_artifacts {
    artifact_identifier = "secondary-artifact"
    type = "CODEPIPELINE"
  }
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_service_role_policy" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRolePolicy"
}

resource "aws_kms_key" "codebuild_encryption_key" {
  description = "KMS key for CodeBuild encryption"
  enable_key_rotation = true
}

resource "aws_s3_bucket" "results_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"
  tags = {
    Name = "cs-class-autograder-results"
  }
}

resource "aws_s3_bucket_policy" "results_bucket_policy" {
  bucket = aws_s3_bucket.results_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:PutObject"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Resource = "${aws_s3_bucket.results_bucket.arn}/*"
      }
    ]
  })
}
```

