  role       = aws_iam_role.autograder_role.name
}

resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "cs-class-autograder-results-${var.github_repo##*/}"
  acl    = "private"

  tags = {
    Name = "CS-Class-Autograder-Results"
  }
}

resource "aws_codebuild_project" "autograder_project" {
  name = "cs-class-autograder-project"

  service_role = aws_iam_role.autograder_role.arn

  source {
    type        = "GitHub"
    location    = var.github_repo
    git_clone_depth = 1
    insecure_ssl = true
    report_build_status = true
    auth {
      type = "OAUTH_TOKEN"
      token = var.github_token
    }
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results_bucket.bucket
  }

  environment {
    type = "LINUX_CONTAINER"
    image = "aws/codebuild/standard:4.0"
    compute_type = "BUILD_GENERAL1_SMALL"
  }

  cache {
    type = "LOCAL_DOCKER_LAYER_CACHE"
  }

  build_spec = <<EOF
version: 0.2

phases:
  pre_build:
    commands:
      - echo "Running pre-build commands..."
  build:
    commands:
      - echo "Building student code..."
  post_build:
    commands:
      - echo "Post-build commands..."
EOF
}
