provider "aws" {
  region = "us-east-1"
}

variable "account_id" {
  default = "your_account_id_here"
}

resource "aws_api_gateway_rest_api" "cat_picture_api" {
  name = "CatPictureAPI"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-${var.account_id}"
  acl    = "private"

  lifecycle_rule {
    enabled     = true
    expiration {
      days = 30
    }
  }

  cors_rule {
    allowed_methods   = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
  }
}

resource "aws_lambda_function" "cat_picture_generator" {
  function_name = "CatPictureGenerator"
  role          = aws_iam_role.cat_picture_role.arn

  runtime       = "nodejs14.x"
  handler       = "index.handler"
  code         = filebase64("${path.module}/cat_picture_generator.zip")

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

resource "aws_iam_role" "cat_picture_role" {
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "CatPicturePolicy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = "s3:PutObject"
          Effect = "Allow"
          Resource = "${aws_s3_bucket.cat_pictures_bucket.arn}/*"
        }
      ]
    })
  }
}
```

