    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_s3_bucket.video_streaming_bucket.id
    viewer_protocol_policy = "allow-all"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
