provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  default     = "example.com"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket for storing video content"
  default     = "video-streaming-bucket"
}

resource "aws_cloudfront_origin_access_control" "video-streaming-origin-access-control" {
  name             = "video-streaming-oac"
  origin_access_control_origin_type = "s3"
  signing_behavior       = "allow-all"
  signing_protocol       = "sigv4"
}

resource "aws_cloudfront_distribution" "video-streaming-distribution" {
  enabled = true

  origin {
    domain_name = aws_s3_bucket.video-streaming-bucket.bucket_domain_name
    origin_id   = "video-streaming-s3-origin"
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "video-streaming-s3-origin"
    viewer_protocol_policy = "allow-all"

    response_headers_policy_id = aws_cloudfront_response_headers_policy.video-streaming-response-headers-policy.id
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    ssl_support_method = "sni-only"
    acm_certificate_arn = "arn:aws:acm:us-east-1:123456789012:certificate/12345678-1234-1234-1234-123456789012"
  }

  logging_config {
    bucket = "my-cloudfront-logs.s3.amazonaws.com"
    include_cookies = false
    prefix = "video-streaming/"
  }

  tags = {
    Name = "Video Streaming Distribution"
  }
}

resource "aws_cloudfront_response_headers_policy" "video-streaming-response-headers-policy" {
  name = "video-streaming-rhp"

  cors_config {
    access_control_allow_credentials = false
    access_control_allow_headers   = ["*"]
    access_control_allow_methods   = ["GET", "HEAD"]
    access_control_allow_origins   = ["*"]
    access_control_expose_headers = ["ETag"]
    max_age_seconds               = 86400
  }

  security_headers_config {
    content_security_policy = "default-src 'self'; script-src 'self' https://cdn.example.com; style-src 'self' https://cdn.example.com; img-src 'self' https://cdn.example.com; frame-src 'self'"
    strict_transport_security = "max-age=31536000; includeSubdomains; preload"
    x_frame_options           = "DENY"
    x_content_type_options   = "nosniff"
  }

  custom_headers_config {
    header {
      header_name = "X-Custom-Header"
      header_value = "CustomValue"
    }
  }
}

resource "aws_route53_zone" "video-streaming-zone" {
  name = var.domain_name

  vpc {
    vpc_id = "vpc-12345678"
    vpc_region = "us-east-1"
  }

  tags = {
    Name = "Video Streaming Zone"
  }
}

resource "aws_s3_bucket" "video-streaming-bucket" {
  bucket = var.s3_bucket_name

  acl = "private"

  cors_rule {
    allowed_methods   = ["GET", "HEAD", "PUT", "POST", "DELETE"]
    allowed_origins   = ["*"]
    allowed_headers   = ["*"]
    expose_headers   = ["ETag"]
    max_age_seconds   = 86400
  }

  lifecycle_rule {
    enabled = true
    id      = "delete-old-objects"
    prefix  = "old/"
    expiration {
      days = 30
    }
  }

  tags = {
    Name = "Video Streaming Bucket"
  }
}

resource "aws_s3_bucket_website" "video-streaming-website" {
  bucket = aws_s3_bucket.video-streaming-bucket.bucket

