provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

variable "security_group_name" {
  description = "Name of the security group"
  default     = "video-streaming-sg"
}

variable "elb_name" {
  description = "Name of the load balancer"
  default     = "video-streaming-elb"
}

variable "alb_target_group_name" {
  description = "Name of the ALB target group"
  default     = "video-streaming-alb-target-group"
}

variable "route53_zone_name" {
  description = "Name of the Route53 zone"
  default     = "example.com"
}

variable "route53_record_name" {
  description = "Name of the Route53 record"
  default     = "www"
}

variable "instance_type" {
  description = "Type of EC2 instance"
  default     = "t3.micro"
}

resource "aws_vpc" "video-streaming-vpc" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "video-streaming-subnet" {
  vpc_id           = aws_vpc.video-streaming-vpc.id
  cidr_block       = var.subnet_cidr_block
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "video-streaming-sg" {
  name        = var.security_group_name
  description = "Security group for video streaming"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elb" "video-streaming-elb" {
  name               = var.elb_name
  subnets             = [aws_subnet.video-streaming-subnet.id]
  security_groups    = [aws_security_group.video-streaming-sg.id]
  listeners          = [
    {
      instance_port          = 80
      instance_protocol      = "http"
      lb_port                = 80
      lb_protocol            = "http"
    },
    {
      instance_port          = 443
      instance_protocol      = "https"
      lb_port                = 443
      lb_protocol            = "https"
      ssl_certificate_id     = aws_acm_certificate.example.id
    }
  ]

  access_logs {
    bucket = aws_s3_bucket.access_logs.bucket
    prefix = "elb-access-logs/"
  }

  health_check {
    healthy_threshold   = 2
    interval            = 30
    target              = "HTTP:80/index.html"
    timeout             = 5
    unhealthy_threshold = 2
  }
}

resource "aws_alb_target_group" "video-streaming-alb-target-group" {
  name               = var.alb_target_group_name
  port                = 80
  protocol            = "HTTP"
  vpc_id              = aws_vpc.video-streaming-vpc.id
  health_check {
    enabled         = true
    healthy_threshold = 2
    interval          = 30
    path              = "/health"
    port              = 80
    protocol          = "HTTP"
    timeout           = 5
    unhealthy_threshold = 2
  }
}

resource "aws_route53_zone" "video-streaming-zone" {
  name = var.route53_zone_name
}

resource "aws_route53_record" "video-streaming-record" {
  name       = var.route53_record_name
  type       = "A"
  zone_id    = aws_route53_zone.video-streaming-zone.id
  alias {
    name                  = aws_elb.video-streaming-elb.dns_name
    zone_id                 = aws_elb.video-streaming-elb.zone_id
    evaluate_target_health = true
  }
}

resource "aws_instance" "video-streaming-instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = var.instance_type
  subnet_id      = aws_subnet.video-streaming-subnet.id
  security_groups = [aws_security_group.video-streaming-sg.id]
  associate_public_ip_address = true
}

resource "aws_acm_certificate" "example" {
  domain_name = "${var.route53_record_name}.${var.route53_zone_name}"
}

resource "aws_s3_bucket" "access_logs" {
  bucket = "video-streaming-access-logs-${var.route53_zone_name}"
}
