LLM Output #0:
```hcl
provider "aws" {
  region = "us-west-2"
}

data "aws_availability_zones" "available" {}

variable "db_instance_class" {
  description = "The class of the PostgreSQL database instance."
  default     = "db.t3.micro"
}

variable "db_instance_allocated_storage" {
  description = "The amount of storage (in GB) to allocate for the database instance."
  default     = 20
}

variable "db_instance_backup_retention_period" {
  description = "The number of days to retain automated backups."
  default     = 7
}

variable "db_instance_backup_window" {
  description = "The daily time range during which automated backups are created (e.g., '03:00-09:00')."
  default     = "03:00-09:00"
}

variable "db_instance_character_set_name" {
  description = "The character set name for the database."
  default     = "utf8mb4"
}

variable "db_instance_copy_tags_to_snapshot" {
  description = "Whether to copy tags from the source DB instance to the new DB instance."
  default     = true
}

variable "db_instance_engine_version" {
  description = "The version of the PostgreSQL database engine."
  default     = "13.6"
}

variable "db_instance_name" {
  description = "The name of the database."
  default     = "mydatabase"
}

variable "db_subnet_group_name" {
  description = "The name of the DB subnet group."
  default     = "mydbsubnetgroup"
}

variable "db_security_group_name" {
  description = "The name of the security group."
  default     = "mydbsg"
}

variable "db_subnet_ids" {
  description = "The IDs of the subnets to place the database instance."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "db_vpc_id" {
  description = "The ID of the VPC to place the database instance."
  default     = "vpc-12345678"
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  count       = length(var.db_subnet_ids)
  vpc_id      = aws_vpc.vpc.id
  cidr_block  = cidrsubnet(aws_vpc.vpc.cidr_block, 2, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name        = var.db_subnet_group_name
  subnet_ids   = aws_subnet.subnet.*.id
}

resource "aws_security_group" "db_security_group" {
  name        = var.db_security_group_name
  description = "Security group for the database instance."
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "db_instance" {
  instance_class = var.db_instance_class
  allocated_storage = var.db_instance_allocated_storage
  backup_retention_period = var.db_instance_backup_retention_period
  backup_window = var.db_instance_backup_window
  character_set_name = var.db_instance_character_set_name
  copy_tags_to_snapshot = var.db_instance_copy_tags_to_snapshot
  engine_version = var.db_instance_engine_version
  db_name = var.db_instance_name
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db_security_group.id]
}
```

