provider "aws" {
  region = "us-west-2"
}

variable "iam_role_arn" {
  description = "ARN of the IAM role to attach to the RDS instance"
  type        = string
  default     = "arn:aws:iam::123456789012:role/example-role"
}

variable "s3_bucket_arn" {
  description = "ARN of the S3 bucket for SQL Server audit logs"
  type        = string
  default     = "arn:aws:s3:::example-bucket"
}

resource "aws_db_option_group" "option_group_pike" {
  engine_name         = "sqlserver-ee"
  major_engine_version = "11"

  option {
    option_name = "SQLSERVER_AUDIT"

    option_settings {
      name  = "AuditLogDestinationType"
      value = "S3"
    }

    option_settings {
      name  = "AuditLogLocation"
      value = "${var.s3_bucket_arn}"
    }

    option_settings {
      name  = "AuditLogRetentionPeriod"
      value = "30"
    }

    option_settings {
      name  = "AuditLogIngestionRoleArn"
      value = "${var.iam_role_arn}"
    }
  }

  option {
    option_name = "TDE"
  }
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name        = "db-subnet-group-pike"
  description = "Subnet group for the RDS instance"

  subnet_ids = [
    "subnet-12345678",  # Replace with actual subnet IDs
    "subnet-23456789",  # Replace with actual subnet IDs
    "subnet-34567890",  # Replace with actual subnet IDs
  ]
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg-pike"
  description = "Security group for the RDS instance"

  ingress {
    cidr_blocks = ["0.0.0.0/0"]
    protocol   = "-1"
    from_port   = 11
    to_port     = 11
  }
}

resource "aws_db_instance" "db_instance" {
  engine               = "sqlserver-ee"
  engine_version       = "11.00.2100.1600"
  instance_class       = "db.t3.micro"
  allocated_storage    = 20
  storage_type        = "gp2"
  username            = "admin"
  password            = "password123"
