    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "sg_proxy" {
  name        = "aurora-proxy-sg"
  description = "Security group for Aurora Proxy"
  vpc_id       = aws_vpc.vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "aurora_mysql_cluster" {
  engine              = "aurora-mysql"
  engine_version      = "5.7.mysql_aurora.2.07.1"
  allocated_storage    = 20
  storage_encrypted   = true
  backup_retention_period = 7
  enable_performance_insights = true
  performance_insights_kms_key_id = aws_kms_key.performance_insights.key_id
  performance_insights_retention_period = 7
  cluster_identifier = "${var.snapshot_name}-${terraform.workspace}"
  cluster_identifier_prefix = "aurora-cluster"
  db_subnet_group_name = aws_db_subnet_group.subnet_group.name
  vpc_security_group_ids = [aws_security_group.sg_rds.id]

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_rds_cluster_instance" "aurora_mysql_instance" {
  cluster_identifier = aws_rds_cluster.aurora_mysql_cluster.cluster_identifier
  engine              = aws_rds_cluster.aurora_mysql_cluster.engine
  instance_class     = "db.t3.micro"
