  subnets = [aws_subnet.public_subnet.id]

  security_groups = [aws_security_group.lb_sg.id]

  tags = var.name_or_tags

  access_logs {
    bucket = aws_s3_bucket.lb_access_logs.bucket
    enabled = true
    prefix = "lb-access-logs/"
  }

  connection_logs {
    bucket = aws_s3_bucket.lb_connection_logs.bucket
    enabled = true
    prefix = "lb-connection-logs/"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_s3_bucket" "lb_access_logs" {
