  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "lb_connection_logs" {
  bucket = "my-lb-connection-logs-${var.name_or_tags.Name}"
  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }
}
