provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  count = 2
  cidr_block = cidrsubnet(aws_vpc.example.cidr_block, 8, count.index)
  vpc_id     = aws_vpc.example.id
}

resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Allow HTTP and HTTPS traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "example" {
  name               = "example-lb"
  subnets             = aws_subnet.example[*].id
  security_groups     = [aws_security_group.example.id]
  internal           = false
  load_balancer_type = "application"
  enable_http2       = true
  enable_tls_version_and_cipher_suite_headers = true

  access_logs {
    bucket = "example-lb-access-logs"
    enabled = true
    prefix  = "logs/"
  }

  connection_logs {
    bucket = "example-lb-connection-logs"
    enabled = true
    prefix  = "logs/"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_alb_target_group" "example" {
  name               = "example-tg"
  port                = 80
  protocol            = "HTTP"
  vpc_id              = aws_vpc.example.id
  health_check_path = "/"
  health_check_protocol = "HTTP"
  health_check_port = "traffic-port"
  health_check_interval_seconds = 30
  health_check_timeout_seconds = 5
  health_check_success_count_threshold = 2
  health_check_failure_count_threshold = 2
  deregistration_delay_seconds = 300
  slow_start_seconds = 300
  stickiness_cookie_duration_seconds = 86400
  stickiness_type = "lb_cookie"
}

resource "aws_lb_target_group_attachment" "example" {
  target_group_arn = aws_alb_target_group.example.arn
  target_id       = aws_instance.example[0].id
  port            = 80
}
