provider "aws" {
  region = "us-west-2"  # Replace with your desired AWS region
}

variable "db_subnet_ids" {
  description = "List of subnet IDs for the RDS cluster"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]  # Replace with your actual subnet IDs
}

variable "db_instance_class" {
  description = "Instance class for the RDS cluster"
  type        = string
  default     = "db.t3.micro"  # Replace with your desired instance class
}

variable "db_cluster_identifier" {
  description = "Identifier for the RDS cluster"
  type        = string
  default     = "postgres-cluster"  # Replace with your desired cluster identifier
}

variable "db_cluster_parameter_group_name" {
  description = "Name of the DB parameter group"
  type        = string
  default     = "postgres-param-group"  # Replace with your desired parameter group name
}

variable "db_subnet_group_name" {
  description = "Name of the DB subnet group"
  type        = string
  default     = "postgres-subnet-group"  # Replace with your desired subnet group name
}

resource "aws_security_group" "postgres_sg" {
  name        = "postgres-sg"
  description = "Security group for the PostgreSQL cluster"

  ingress {
    cidr_blocks = ["0.0.0.0/0"]
    protocol   = "-1"
    from_port   = 0
    to_port     = 65535
  }

  egress {
    cidr_blocks = ["0.0.0.0/0"]
    protocol   = "-1"
    from_port   = 0
    to_port     = 65535
  }
}

resource "aws_db_parameter_group" "postgres_param_group" {
  family       = "postgres14"
  name         = var.db_cluster_parameter_group_name
  description = "Parameter group for PostgreSQL"

  parameter {
    name         = "max_connections"
    value        = "100"
    apply_method = "immediate"
  }

  parameter {
    name         = "shared_prepared_transactions"
    value        = "on"
    apply_method = "immediate"
  }
}

resource "aws_db_subnet_group" "postgres_subnet_group" {
  name         = var.db_subnet_group_name
  description = "Subnet group for PostgreSQL"
  subnet_ids    = var.db_subnet_ids
}

resource "aws_rds_cluster" "postgres_cluster" {
  engine              = "postgres"
  engine_version      = "14.6"
  allocated_storage    = 20
  cluster_identifier = var.db_cluster_identifier
  db_subnet_group_name = aws_db_subnet_group.postgres_subnet_group.name
  db_parameter_group_name = aws_db_parameter_group.postgres_param_group.name
  vpc_security_group_ids = [aws_security_group.postgres_sg.id]
}

resource "aws_rds_cluster_instance" "postgres_instance" {
  cluster_identifier = aws_rds_cluster.postgres_cluster.id
  engine             = aws_rds_cluster.postgres_cluster.engine
  instance_class     = var.db_instance_class
  db_subnet_group_name = aws_db_subnet_group.postgres_subnet_group.name
  apply_immediately = true
}
```

